{"result":"{
  "metadata": {
    "id": "256835585",
    "title": "Technical Solution Design – PWA",
    "type": "page",
    "created": "",
    "updated": "",
    "url": "https://zimmermannworkboard.atlassian.net/wiki/spaces/SFCC/pages/256835585",
